/*
 * Held — WebGL 3D view with the heart model (progressive enhancement of view3d.js).
 *
 * The page always starts with the 2D-canvas view, which works offline on the controller's access
 * point. HeldViewGL.upgrade() then tries to load three.js from the CDN (see the import map in
 * index.htm). If that works and WebGL is available, it swaps in a WebGL view with the same
 * interface (setStrips, draw, resetView, autoRotate, glow, shell, highlight, onPick, onChange) and
 * loads the heart model. Without internet nothing changes; ?lite skips the upgrade.
 *
 * The model is a script (window.HeldHeartModel = {glb: base64}) built by
 * tools/held/heart/build_heart.py and hosted on istariarts.org: script tags load cross-origin
 * without CORS headers, so the controller's own page can use it too. The heart is drawn at its
 * real size (millimetres, centred on its bounding box) as translucent PLA, lit from inside by
 * each strip's average LED colour.
 */
(function (root) {
	'use strict';

	const THREE_BASE = 'https://cdn.jsdelivr.net/npm/three@0.170.0/';  // keep in sync with the import map in index.htm
	const MODEL_URL = 'https://istariarts.org/static/held/heart_model.js';
	const LOAD_TIMEOUT_MS = 10000;
	const LED_MM = 11;             // lit LED core diameter
	const BODY_MM = 9;             // unlit LED body diameter
	const GLOW_MM = 90;            // glow halo diameter
	const MARK_MM = 26;            // origin / highlight ring diameter
	const BODY_RGB = [0x2a / 255, 0x1a / 255, 0x16 / 255];  // unlit LED, as in the canvas view
	const HEART_COLOR = 0xf2d9c9;  // natural translucent PLA
	const HEART_OPACITY = 0.07;
	const INNER_LIGHT = 7;         // inner light intensity per unit of mean strip brightness

	const VERT = `
		uniform float uSize;
		uniform float uScale;
		attribute vec3 col;
		varying vec3 vCol;
		void main() {
			vec4 mv = modelViewMatrix * vec4(position, 1.0);
			gl_Position = projectionMatrix * mv;
			gl_PointSize = max(1.5, uSize * uScale / -mv.z);
			vCol = col;
		}`;
	// uKind: 0 = disc, 1 = soft glow, 2 = ring
	const FRAG = `
		uniform float uKind;
		uniform float uAlpha;
		varying vec3 vCol;
		void main() {
			float d = length(gl_PointCoord - 0.5) * 2.0;
			if (d > 1.0) discard;
			float a;
			if (uKind < 0.5) a = 1.0 - smoothstep(0.75, 1.0, d);
			else if (uKind < 1.5) a = exp(-d * d * 6.0) * (1.0 - d);
			else a = smoothstep(0.7, 0.8, d) * (1.0 - smoothstep(0.92, 1.0, d));
			if (a <= 0.003) discard;
			gl_FragColor = vec4(vCol, a * uAlpha);
		}`;

	function timeout(p, ms) {
		return Promise.race([p, new Promise((res, rej) => setTimeout(() => rej(new Error('timed out')), ms))]);
	}

	function loadModelScript() {
		if (root.HeldHeartModel) return Promise.resolve(root.HeldHeartModel);
		return new Promise((res, rej) => {
			const s = document.createElement('script');
			s.src = new URLSearchParams(location.search).get('heart') || root.HELD_HEART_URL || MODEL_URL;  // ?heart=<url> for testing
			s.onload = () => (root.HeldHeartModel ? res(root.HeldHeartModel) : rej(new Error('model script defined no model')));
			s.onerror = () => rej(new Error('model script did not load'));
			document.head.appendChild(s);
		});
	}

	function b64ToBuffer(b64) {
		const bin = atob(b64), u = new Uint8Array(bin.length);
		for (let i = 0; i < bin.length; i++) u[i] = bin.charCodeAt(i);
		return u.buffer;
	}

	function makeView(THREE) {
		const pointMat = (kind, size, alpha, additive, depthTest) => new THREE.ShaderMaterial({
			uniforms: { uSize: { value: size }, uScale: { value: 1 }, uKind: { value: kind }, uAlpha: { value: alpha } },
			vertexShader: VERT, fragmentShader: FRAG, transparent: true, depthWrite: !additive && depthTest, depthTest: depthTest,
			blending: additive ? THREE.AdditiveBlending : THREE.NormalBlending
		});
		const filled = (n, rgb) => { const a = new Float32Array(3 * n); for (let i = 0; i < 3 * n; i++) a[i] = rgb[i % 3]; return a; };

		class HeldViewGL {
			constructor(canvas, prev) {
				this.cv = canvas;
				this.yaw = prev.yaw; this.pitch = prev.pitch; this.dist = prev.dist;
				this.autoRotate = prev.autoRotate; this.glow = prev.glow; this.shell = prev.shell;
				this.onPick = prev.onPick; this.onChange = prev.onChange; this.highlight = prev.highlight;
				this.strips = []; this.stripCfg = []; this._proj = [];
				this.gl = true;

				const r = this.renderer = new THREE.WebGLRenderer({ canvas: canvas, antialias: true, alpha: true });
				r.setClearColor(0x000000, 0);
				this.scene = new THREE.Scene();
				this.camera = new THREE.PerspectiveCamera(38, 1, 10, 20000);
				this.scene.add(this.camera);
				this.world = new THREE.Group();
				this.scene.add(this.world);

				this.scene.add(new THREE.AmbientLight(0xffffff, 0.15));
				const key = new THREE.DirectionalLight(0xffe6d8, 0.6);
				key.position.set(-0.5, 0.8, 1);
				this.camera.add(key);   // lighting follows the view
				this.lights = [];
				for (let i = 0; i < 4; i++) {
					const l = new THREE.PointLight(0xffffff, 0, 0, 0);
					this.lights.push(l);
					this.world.add(l);
				}

				this.heartMat = new THREE.MeshStandardMaterial({ color: HEART_COLOR, roughness: 0.55, metalness: 0, transparent: true, opacity: HEART_OPACITY, depthWrite: false, side: THREE.DoubleSide });
				this.heart = null;
				this.wire = this._wireShell();
				this.world.add(this.wire);

				this.matBody = pointMat(0, BODY_MM, 1, false, true);
				this.matGlow = pointMat(1, GLOW_MM, 0.5, true, false);
				this.matCore = pointMat(0, LED_MM, 1, true, false);
				this.matMark = pointMat(2, MARK_MM, 0.8, false, false);
				this.matHi = pointMat(2, MARK_MM * 1.25, 1, false, false);
				this.ledGroup = new THREE.Group();
				this.world.add(this.ledGroup);
				this.markGeo = null;
				this.hiGeo = new THREE.BufferGeometry();
				this.hiGeo.setAttribute('position', new THREE.BufferAttribute(new Float32Array(3), 3));
				this.hiGeo.setAttribute('col', new THREE.BufferAttribute(new Float32Array([0x7f / 255, 0xd0 / 255, 1]), 3));
				this.hiPts = new THREE.Points(this.hiGeo, this.matHi);
				this.hiPts.frustumCulled = false;
				this.hiPts.renderOrder = 5;
				this.world.add(this.hiPts);

				HeldView3D.bindOrbit(this);
				this.setStrips(prev.stripCfg || []);
			}

			resetView() { this.yaw = 0; this.pitch = 0; this.dist = 2100; }
			_emit(what) { if (this.onChange) this.onChange(what); }

			// the bounding ellipsoid as a wireframe, shown until (or if never) the model arrives
			_wireShell() {
				const S = HeldView3D.SHELL, DEG = Math.PI / 180, v = [];
				const ring = (fn) => { for (let a = 0; a < 360; a += 10) v.push(...fn(a), ...fn(a + 10)); };
				for (let lat = -60; lat <= 60; lat += 30) {
					const c = Math.cos(lat * DEG), y = S.ry * Math.sin(lat * DEG);
					ring((a) => [S.rx * c * Math.cos(a * DEG), y, S.rz * c * Math.sin(a * DEG)]);
				}
				for (let lon = 0; lon < 180; lon += 30) {
					ring((a) => [S.rx * Math.cos(a * DEG) * Math.cos(lon * DEG), S.ry * Math.sin(a * DEG), S.rz * Math.cos(a * DEG) * Math.sin(lon * DEG)]);
				}
				const g = new THREE.BufferGeometry();
				g.setAttribute('position', new THREE.Float32BufferAttribute(v, 3));
				return new THREE.LineSegments(g, new THREE.LineBasicMaterial({ color: 0xa05a46, transparent: true, opacity: 0.18, depthWrite: false }));
			}

			setHeart(gltfScene) {
				gltfScene.traverse((o) => { if (o.isMesh) { o.material = this.heartMat; o.renderOrder = 1; } });
				this.heart = gltfScene;
				this.world.add(gltfScene);
			}

			setStrips(strips) {
				this.stripCfg = strips;
				for (const st of this.strips) { st.ledGeo.dispose(); st.bodyGeo.dispose(); }
				this.ledGroup.clear();
				const marks = [];
				this.strips = strips.map((s) => {
					const geo = HeldView3D.geometry(s);
					const n = geo.n;
					const posAttr = new THREE.BufferAttribute(geo.pos, 3);
					const ledGeo = new THREE.BufferGeometry();
					ledGeo.setAttribute('position', posAttr);
					ledGeo.setAttribute('col', new THREE.BufferAttribute(new Float32Array(3 * n), 3));
					const bodyGeo = new THREE.BufferGeometry();
					bodyGeo.setAttribute('position', posAttr);
					bodyGeo.setAttribute('col', new THREE.BufferAttribute(filled(n, BODY_RGB), 3));
					const body = new THREE.Points(bodyGeo, this.matBody), glow = new THREE.Points(ledGeo, this.matGlow), core = new THREE.Points(ledGeo, this.matCore);
					body.renderOrder = 0; glow.renderOrder = 2; core.renderOrder = 3;
					for (const p of [body, glow, core]) { p.frustumCulled = false; this.ledGroup.add(p); }
					for (const i of geo.origins) if (i < n) marks.push(geo.pos[3 * i], geo.pos[3 * i + 1], geo.pos[3 * i + 2]);
					let cx = 0, cy = 0, cz = 0;
					for (let i = 0; i < n; i++) { cx += geo.pos[3 * i]; cy += geo.pos[3 * i + 1]; cz += geo.pos[3 * i + 2]; }
					return { pos: geo.pos, n: n, origins: geo.origins, ledGeo: ledGeo, bodyGeo: bodyGeo, glow: glow, centre: [cx / n, cy / n, cz / n] };
				});
				if (this.markPts) { this.world.remove(this.markPts); this.markGeo.dispose(); }
				this.markGeo = new THREE.BufferGeometry();
				this.markGeo.setAttribute('position', new THREE.Float32BufferAttribute(marks, 3));
				this.markGeo.setAttribute('col', new THREE.BufferAttribute(filled(marks.length / 3, [1, 210 / 255, 140 / 255]), 3));
				this.markPts = new THREE.Points(this.markGeo, this.matMark);
				this.markPts.frustumCulled = false;
				this.markPts.renderOrder = 4;
				this.world.add(this.markPts);
			}

			_resize() {
				const rect = this.cv.getBoundingClientRect();
				const dpr = Math.min(2, window.devicePixelRatio || 1);
				const w = Math.max(50, Math.round(rect.width * dpr)), h = Math.max(50, Math.round(rect.height * dpr));
				if (w === this._w && h === this._h) return;
				this._w = w; this._h = h;
				this.renderer.setSize(w, h, false);
				// same projection as the canvas view: the FOV spans the smaller canvas dimension
				const half = Math.atan(Math.tan(HeldView3D.FOV / 2) * h / Math.min(w, h));
				this.camera.fov = 2 * half * 180 / Math.PI;
				this.camera.aspect = w / h;
				this.camera.updateProjectionMatrix();
				const scale = h / (2 * Math.tan(half));
				for (const m of [this.matBody, this.matGlow, this.matCore, this.matMark, this.matHi]) m.uniforms.uScale.value = scale;
			}

			draw(colors, gain, dt) {
				this._resize();
				if (this.autoRotate) this.yaw += (dt || 0) * 0.15;
				this.world.rotation.set(this.pitch, this.yaw, 0, 'XYZ');   // yaw about y, then pitch about x, as in the canvas view
				this.camera.position.set(0, 0, this.dist);

				for (let s = 0; s < this.strips.length; s++) {
					const st = this.strips[s], col = colors[s], attr = st.ledGeo.getAttribute('col'), a = attr.array;
					let r = 0, g = 0, b = 0;
					for (let i = 0; i < 3 * st.n; i += 3) {
						a[i] = col ? Math.min(1, col[i] * gain) : 0;
						a[i + 1] = col ? Math.min(1, col[i + 1] * gain) : 0;
						a[i + 2] = col ? Math.min(1, col[i + 2] * gain) : 0;
						r += a[i]; g += a[i + 1]; b += a[i + 2];
					}
					attr.needsUpdate = true;
					st.glow.visible = this.glow;
					const l = this.lights[s];
					if (l) {
						const m = Math.max(r, g, b) / Math.max(1, st.n);
						l.position.set(st.centre[0], st.centre[1], st.centre[2]);
						if (m > 0) l.color.setRGB(r / st.n / m, g / st.n / m, b / st.n / m);
						l.intensity = this.shell ? INNER_LIGHT * m : 0;
					}
				}
				for (let s = this.strips.length; s < this.lights.length; s++) this.lights[s].intensity = 0;

				if (this.heart) this.heart.visible = this.shell;
				this.wire.visible = this.shell && !this.heart;

				const h = this.highlight, hs = h && this.strips[h.s];
				this.hiPts.visible = !!(hs && h.i < hs.n);
				if (this.hiPts.visible) {
					const p = this.hiGeo.getAttribute('position');
					p.setXYZ(0, hs.pos[3 * h.i], hs.pos[3 * h.i + 1], hs.pos[3 * h.i + 2]);
					p.needsUpdate = true;
				}
				this.renderer.render(this.scene, this.camera);
			}

			_pick(e) {
				const v = new THREE.Vector3(), W = this.cv.width, H = this.cv.height;
				this.world.updateMatrixWorld();
				this._proj.length = 0;
				for (let s = 0; s < this.strips.length; s++) {
					const st = this.strips[s];
					for (let i = 0; i < st.n; i++) {
						v.set(st.pos[3 * i], st.pos[3 * i + 1], st.pos[3 * i + 2]).applyMatrix4(this.world.matrixWorld).project(this.camera);
						this._proj.push({ x: (v.x + 1) / 2 * W, y: (1 - v.y) / 2 * H, s: s, i: i });
					}
				}
				HeldView3D.pickNearest(this, e);
			}
		}
		return HeldViewGL;
	}

	// Resolves to a WebGL view that has replaced prev's canvas, or null (prev keeps running).
	async function upgrade(prev) {
		if (/[?&]lite\b/.test(location.search)) return null;
		try {
			const mods = await timeout(Promise.all([import('three'), import('three/addons/loaders/GLTFLoader.js'), import('three/addons/loaders/DRACOLoader.js')]), LOAD_TIMEOUT_MS);
			const THREE = mods[0];
			const cv = document.createElement('canvas');
			cv.id = prev.cv.id;
			cv.className = prev.cv.className;
			const view = new (makeView(THREE))(cv, prev);   // throws without WebGL
			prev.cv.replaceWith(cv);
			timeout(loadModelScript(), LOAD_TIMEOUT_MS).then((m) => {
				const draco = new mods[2].DRACOLoader();
				draco.setDecoderPath(THREE_BASE + 'examples/jsm/libs/draco/gltf/');
				const loader = new mods[1].GLTFLoader();
				loader.setDRACOLoader(draco);
				loader.parse(b64ToBuffer(m.glb), '', (gltf) => { view.setHeart(gltf.scene); draco.dispose(); }, (err) => console.info('Held: heart model failed to parse', err));
			}).catch((e) => console.info('Held: heart model unavailable (' + e.message + ')'));
			return view;
		} catch (e) {
			console.info('Held: WebGL view unavailable (' + (e && e.message) + '); using the canvas view');
			return null;
		}
	}

	root.HeldViewGL = { upgrade: upgrade };
})(window);
